<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { appointmentStatusLabels, createAppointment, rescheduleAppointment, searchAppointments, updateAppointmentStatus, type Appointment, type AppointmentAction, type AppointmentStatus } from '@/api/appointments'
const date = ref(new Date().toISOString().slice(0, 10)); const status = ref<AppointmentStatus | ''>('CONFIRMED'); const appointments = ref<Appointment[]>([]); const loading = ref(false); const saving = ref(false); const errorMessage = ref(''); const successMessage = ref('')
const form = ref({ patientId: '', therapistId: '1', serviceId: '1', startAt: '09:00', note: '' })
async function load() { loading.value = true; errorMessage.value = ''; try { appointments.value = (await searchAppointments(date.value, status.value || undefined)).items } catch (e) { errorMessage.value = e instanceof Error ? e.message : 'เกิดข้อผิดพลาด' } finally { loading.value = false } }
async function submit() { successMessage.value = ''; errorMessage.value = ''; if (!form.value.patientId) { errorMessage.value = 'กรุณาระบุ Patient ID'; return }; saving.value = true; try { await createAppointment({ branchCode: 'RP', patientId: Number(form.value.patientId), therapistId: Number(form.value.therapistId), serviceId: Number(form.value.serviceId), startAt: `${date.value}T${form.value.startAt}:00+07:00`, note: form.value.note || undefined }); successMessage.value = 'สร้างนัดหมายสำเร็จ'; form.value.note = ''; await load() } catch (e) { errorMessage.value = e instanceof Error ? e.message : 'ไม่สามารถสร้างนัดหมายได้' } finally { saving.value = false } }
function formatTime(value: string) { return new Date(value).toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' }) }
// ยังไม่ถึงคลินิก: ยังเช็กอิน เลื่อนนัด ยกเลิก หรือบันทึกไม่มาตามนัดได้
function awaitingArrival(item: Appointment) { return item.status === 'CONFIRMED' || item.status === 'RESCHEDULED' }
async function changeStatus(item: Appointment, action: AppointmentAction) { const reason = action === 'cancel' ? window.prompt('เหตุผลการยกเลิก') : undefined; if (action === 'cancel' && !reason?.trim()) return; try { await updateAppointmentStatus(item.id, action, reason || undefined); successMessage.value = 'เปลี่ยนสถานะสำเร็จ'; await load() } catch (e) { errorMessage.value = e instanceof Error ? e.message : 'ไม่สามารถเปลี่ยนสถานะได้' } }
async function reschedule(item: Appointment) { const value = window.prompt('วันเวลาใหม่ เช่น 2026-09-12T09:00:00+07:00', item.startAt); if (!value?.trim()) return; try { await rescheduleAppointment(item.id, value.trim(), item.therapist.id); successMessage.value = 'เลื่อนนัดหมายสำเร็จ'; await load() } catch (e) { errorMessage.value = e instanceof Error ? e.message : 'ไม่สามารถเลื่อนนัดหมายได้' } }
onMounted(() => void load())
</script>
<template>
  <section class="patient-page"><header class="patient-page-header"><div><p class="eyebrow">APPOINTMENTS</p><h1>นัดหมาย</h1><p class="page-subtitle">สร้างและตรวจสอบนัดหมายของคลินิก</p></div></header>
    <form class="form-card" @submit.prevent="submit"><h2>สร้างนัดหมาย</h2><div class="form-grid"><label>วันที่ *<input v-model="date" type="date" required /></label><label>Patient ID *<input v-model="form.patientId" type="number" min="1" required /></label><label>Therapist<select v-model="form.therapistId"><option value="1">นักกายภาพบำบัด คนที่หนึ่ง</option><option value="2">นักกายภาพบำบัด คนที่สอง</option></select></label><label>Service<select v-model="form.serviceId"><option value="1">กายภาพบำบัดทั่วไป 30 นาที</option><option value="2">กายภาพบำบัดทั่วไป 60 นาที</option><option value="3">ประเมินอาการครั้งแรก</option></select></label><label>เวลาเริ่ม *<input v-model="form.startAt" type="time" required /></label><label class="wide">หมายเหตุ<textarea v-model="form.note" rows="2" maxlength="500" /></label></div><div class="actions end"><button class="primary" type="submit" :disabled="saving">{{ saving ? 'กำลังบันทึก...' : 'สร้างนัดหมาย' }}</button></div><p v-if="successMessage" class="success" role="status">{{ successMessage }}</p><p v-if="errorMessage" class="error" role="alert">{{ errorMessage }}</p></form>
    <div class="patient-search-form"><label>ดูรายการวันที่ {{ date }}<select v-model="status" @change="load"><option v-for="(label, value) in appointmentStatusLabels" :key="value" :value="value">{{ label }}</option><option value="">ทุกสถานะ</option></select></label></div>
    <div v-if="loading" class="state-card">กำลังโหลด...</div><div v-else-if="!appointments.length" class="state-card">ยังไม่มีนัดหมายในวันที่เลือก</div><div v-else class="patient-results"><article v-for="item in appointments" :key="item.id" class="patient-result-card"><div><span class="patient-hn">{{ formatTime(item.startAt) }}–{{ formatTime(item.endAt) }}</span><h2>{{ item.patient.fullName }}</h2><p>{{ item.service.name }} · {{ item.therapist.fullName }}</p></div><div><strong>{{ appointmentStatusLabels[item.status] }}</strong><div class="actions"><button v-if="awaitingArrival(item)" class="secondary" @click="changeStatus(item, 'check-in')">เช็กอิน</button><button v-if="item.status === 'ARRIVED'" class="secondary" @click="changeStatus(item, 'start-service')">เริ่มบริการ</button><button v-if="item.status === 'IN_SERVICE'" class="secondary" @click="changeStatus(item, 'complete')">เสร็จสิ้น</button><button v-if="awaitingArrival(item)" class="secondary" @click="changeStatus(item, 'no-show')">ไม่มาตามนัด</button><button v-if="awaitingArrival(item) || item.status === 'ARRIVED'" class="secondary" @click="changeStatus(item, 'cancel')">ยกเลิก</button></div></div></article></div>
  </section>
</template>
